1	// 跨集详情读取：gid → 集 → detail 分片按 meta.fields 列序拆字段
2	// （detail.ux 的历史集读取逻辑硬编码 /common 路径与 v4 列序，无法吃资料集格式——此处统一适配）
3	// ⚠️ 必须显式 import：各 JS 模块作用域独立，DATASETS/decodeGlobalId/ensureEngine 不会凭空可见
4	import { DATASETS, ensureEngine, decodeGlobalId } from './DatasetManager.js'
5	
6	function _readText(uri) {
7	  // file 用函数内 require（与引擎一致——顶层静态 import 原生模块在快应用互操作下不可靠）
8	  var file = require('@system.file')
9	  return new Promise(function(resolve) {
10	    file.readText({
11	      uri: uri,
12	      success: function(res) { resolve(res.text || '') },
13	      fail: function() { resolve('') }
14	    })
15	  })
16	}
17	
18	// fields 声明在 meta.json；meta.txt 是引擎吃的 v4 兼容壳（无 fields 键）
19	// 兼容两种声明：字符串数组 ["source","content"] / 对象数组 [{name, position}]
20	async function _loadMeta(eng) {
21	  var raw = await _readText(eng.basePath + 'meta.json')
22	  var metaObj = {}
23	  try { metaObj = JSON.parse(raw) } catch (e) { metaObj = {} }
24	  if (!metaObj.fields) {
25	    raw = await _readText(eng.basePath + 'meta.txt')
26	    try { metaObj = JSON.parse(raw) } catch (e2) { metaObj = {} }
27	  }
28	  var names = []
29	  var fd = (metaObj.fields && metaObj.fields.detail) || []
30	  for (var i = 0; i < fd.length; i++) {
31	    var f = fd[i]
32	    var idx = (f && f.position !== undefined) ? (f.position - 2) : i
33	    names[idx] = (typeof f === 'string') ? f : f.name
34	  }
35	  return {
36	    detailChunkSize: metaObj.detailChunkSize || (eng.detailChunkSize || 100),
37	    detFieldNames: names.length ? names : ['详情']
38	  }
39	}
40	
41	async function getDetailByGlobalId(gid) {
42	  var d = decodeGlobalId(gid)
43	  var ds = null
44	  for (var i = 0; i < DATASETS.length; i++) {
45	    if (DATASETS[i].id === d.dsId) { ds = DATASETS[i]; break }
46	  }
47	  if (!ds) return null
48	  var eng = ensureEngine(ds)
49	  var mapDoc = await eng.getDoc(d.localId)
50	
51	  var meta = await _loadMeta(eng)
52	
53	  // 读 detail 分片找 localId 行
54	  var chunkId = Math.floor(d.localId / meta.detailChunkSize)
55	  var raw = await _readText(eng.basePath + 'detail_' + chunkId + '.txt')
56	
57	  var rows = raw.split('\n')
58	  var line = null
59	  for (var ri = 0; ri < rows.length; ri++) {
60	    var cols = rows[ri].split('|')
61	    if (parseInt(cols[0], 10) === d.localId) { line = cols; break }
62	  }
63	
64	  var details = []
65	  if (line) {
66	    // detail 行：localId|关键词|字段值1|字段值2...（列 2 起按 fields.detail 顺序）
67	    for (var ci = 2; ci < line.length; ci++) {
68	      var name = meta.detFieldNames[ci - 2] || ('详情' + (ci - 1))
69	      // 物化时真实换行编码为字面 \n 两字符（| 是列分隔符，裸换行会断行），这里还原
70	      var value = (line[ci] || '').replace(/\\n/g, '\n')
71	      if (value) details.push({ name: name, value: value })
72	    }
73	  }
74	
75	  return {
76	    isDataset: true,
77	    dsName: ds.name,
78	    title: (mapDoc && mapDoc.title) || '',
79	    // 资料集无年份语义（物化 year=0 → 引擎返回「公元元年」）：年份位显示集标签
80	    yearDisplay: ds.id !== 0 ? ds.tag : ((mapDoc && mapDoc.yearDisplay) || ds.tag),
81	    region: (mapDoc && mapDoc.region) || ds.tag,
82	    keywords: line && line[1] ? line[1].split(',').filter(function(k) { return k }) : [],
83	    details: details
84	  }
85	}
86	
