507	                if (parts.length < 4) continue
508	                ids.push(parseInt(parts[0], 10))
509	                years.push(parseInt(parts[1], 10))
510	                regionIds.push(parseInt(parts[2], 10))
511	                titles.push(parts[3] || '')
512	              }
513	              
514	              var mapData = {
515	                ids: ids,
516	                years: years,
517	                regionIds: regionIds,
518	                titles: titles,
519	                recordCount: ids.length
