540	  
541	  // 启动时只检查缓存，不加载到内存
542	  /**
543	 * 加载 Map（支持预加载策略）
544	 * 快速启动模式下强制跳过预加载
545	 */
546	  async _loadAllMaps() {
547	    if (this.maps.length === 0) {
548	      _logInfo('没有Map配置，跳过加载', 'map')
549	      return
550	    }
551	  
552	    // 快速启动模式跳过预加载
553	    if (this._isQuickLaunch) {
554	      _logInfo('快速启动模式，跳过Map预加载', 'map')
555	      return
556	    }
557	  
558	    var preloadConfig = this.config.mapPreload || { enabled: false, maxMaps: 0 }
559	  
560	    // 按需加载模式：只检查缓存
561	    if (!preloadConfig.enabled) {
562	      await this._checkAllMapsCache()
563	      return
564	    }
565	  
566	    // ====== 预加载模式：直接调用 _ensureMap ======
567	    var maxMaps = preloadConfig.maxMaps || 0
568	    var totalMaps = this.maps.length
569	    var loadCount = (maxMaps === 0) ? totalMaps : Math.min(maxMaps, totalMaps)
570	  
571	    _logInfo('预加载模式：加载前 ' + loadCount + '/' + totalMaps + ' 个Map', 'map')
572	  
573	    for (var i = 0; i < loadCount; i++) {
574	      // 直接用 _ensureMap 加载，它会处理缓存/文件/内存
575	      var mapData = await this._ensureMap(i)
576	      if (mapData) {
577	        _logInfo('Map ' + i + ' 预加载成功', 'map')
578	      } else {
579	        _logWarn('Map ' + i + ' 预加载失败', 'map')
580	      }
581	  
582	      // 每加载 3 个休息 100ms
583	      if (i % 3 === 2) {
584	        await new Promise(resolve => setTimeout(resolve, 100))
585	      }
586	    }
587	  
588	    _logSuccess('Map预加载完成', 'map')
589	  }
590	  
591	/**
592	 * 仅检查 Map 缓存是否存在，不加载到内存
593	 * 用于按需加载模式
594	 */
595	async _checkAllMapsCache() {
596	  _logInfo('检查 ' + this.maps.length + ' 个Map缓存', 'map')
597	  this._cachedMaps = {}
598	  
599	  for (var i = 0; i < this.maps.length; i++) {
600	    try {
601	      var mapData = await this._loadMapFromCache(i)
602	      this._cachedMaps[i] = !!mapData
603	      if (this._cachedMaps[i]) {
604	        _logInfo('Map ' + i + ' 缓存存在', 'map')
605	      } else {
606	        // 尝试构建缓存
607	        mapData = await this._loadMapFromFile(i)
608	        if (mapData) {
609	          this._saveMapToCache(i, mapData)
610	          this._cachedMaps[i] = true
611	          _logInfo('Map ' + i + ' 已构建缓存', 'map')
612	        }
613	      }
614	    } catch(e) {
615	      _logError('检查Map ' + i + ' 失败: ' + e.message, 'map')
616	      this._cachedMaps[i] = false
617	    }
618	    
619	    if (i % 3 === 2) {
620	      await new Promise(resolve => setTimeout(resolve, 5))
621	    }
622	  }
623	  
624	  _logSuccess('Map缓存检查完成', 'map')
625	}
626	  // ========== Map 按需加载（搜索时调用） ==========
627	  async _ensureMap(mapId) {
628	    // 如果已经在内存中，移到最近使用位置
629	    if (this.mapData[mapId]) {
630	      var idx = this.loadedMapsOrder.indexOf(mapId)
631	      if (idx > -1) {
632	        this.loadedMapsOrder.splice(idx, 1)
633	        this.loadedMapsOrder.push(mapId)
634	      }
635	      return this.mapData[mapId]
636	    }
637	    
638	    _logInfo('加载 Map ' + mapId + ' 到内存', 'map')
639	    
640	    var mapData = await this._loadMapFromCache(mapId)
641	    if (!mapData) {
642	      mapData = await this._loadMapFromFile(mapId)
643	      if (mapData) {
644	        this._saveMapToCache(mapId, mapData)
645	      }
646	    }
647	    
648	    if (!mapData) {
649	      _logError('Map ' + mapId + ' 加载失败', 'map')
650	      return null
651	    }
652	    
653	    // ========== 新增：LRU 淘汰 ==========
654	    while (this.loadedMapsOrder.length >= this.maxLoadedMaps) {
655	      var oldest = this.loadedMapsOrder.shift()
656	      delete this.mapData[oldest]
657	      _logInfo('移除 Map ' + oldest + ' 释放内存', 'map')
658	    }
659	    
660	    // 存入内存
661	    this.mapData[mapId] = mapData
662	    this.loadedMapsOrder.push(mapId)
663	    
664	    return mapData
665	  }
666	  
667	  // 从 Map 获取信息（确保 Map 已加载）
668	  async _getMapInfoById(mapId, id) {
669	    var map = await this._ensureMap(mapId)
670	    if (!map) return null
671	    
672	    var ids = map.ids
673	    var left = 0
674	    var right = ids.length - 1
675	    
676	    while (left <= right) {
677	      var mid = Math.floor((left + right) / 2)
678	      if (ids[mid] === id) {
679	        return {
680	          year: map.years[mid],
681	          regionId: map.regionIds[mid],
682	          title: map.titles[mid]
683	        }
684	      } else if (ids[mid] < id) {
685	        left = mid + 1
686	      } else {
687	        right = mid - 1
688	      }
689	    }
690	    return null
691	  }
692	  
693	  _getMapIdById(id) {
