235	    async _loadDetail(id) {
236	  var self = this
237	
238	  if (typeof global.addRuntimeLog === 'function') {
239	    global.addRuntimeLog('[detail] 打开 ID=' + id, 'info')
240	  }
241	
242	  if (id === undefined || id === null) {
243	    this.errorMsg = '事件ID无效'
244	    this.loading = false
