254	        this.yearDisplay = dsDetail.yearDisplay || ''
255	        this.region = dsDetail.region || ''
256	        this.keywordList = dsDetail.keywords && dsDetail.keywords.length ? dsDetail.keywords.slice(0, 12) : [dsDetail.title]
257	        this.detailFields = dsDetail.details
258	        this.loading = false
259	        this.checkFavoriteStatus(id)
260	        if (typeof global.addRuntimeLog === 'function') {
261	          global.addRuntimeLog('[detail] 资料集详情加载成功: ' + this.detailTitle, 'success')
262	        }
263	        return
