269	      this.errorMsg = '资料集详情加载失败: ' + e.message
270	      this.loading = false
271	      if (typeof global.addRuntimeLog === 'function') {
272	        global.addRuntimeLog('[detail] 资料集加载异常: ' + e.message, 'error')
273	      }
274	      return
275	    }
276	  }
277	
278	  this.checkFavoriteStatus(id)
279	
280	  // ==========================================================
281	  // 获取 Map 数据
282	  // ==========================================================
283	  var mapData = null
284	
285	  // 第一步：尝试从引擎获取（300ms 超时）
286	  try {
287	    var engineResult = await Promise.race([
288	      global.getItemById(id),
289	      new Promise(function(resolve) {
290	        setTimeout(function() {
291	          resolve(null)
292	        }, 300)
293	      })
294	    ])
295	    if (engineResult) {
296	      mapData = engineResult
297	      if (typeof global.addRuntimeLog === 'function') {
298	        global.addRuntimeLog('[detail] 引擎获取 Map 成功（内存命中）', 'info')
299	      }
300	    }
301	  } catch(e) {
302	    if (typeof global.addRuntimeLog === 'function') {
303	      global.addRuntimeLog('[detail] 引擎获取异常: ' + e.message, 'warn')
304	    }
305	  }
306	
307	  // 第二步：引擎超时或失败 → 从缓存加载 Map 到内存
308	  if (!mapData) {
309	    if (typeof global.addRuntimeLog === 'function') {
310	      global.addRuntimeLog('[detail] 引擎未命中，尝试从缓存加载 Map', 'info')
311	    }
312	    var loaded = await this._loadMapFromCache(id)
313	    if (loaded) {
314	      // 缓存加载成功 → 再试一次引擎
315	      try {
316	        var result2 = await global.getItemById(id)
317	        if (result2) {
318	          mapData = result2
319	          if (typeof global.addRuntimeLog === 'function') {
320	            global.addRuntimeLog('[detail] 缓存加载后引擎获取成功', 'success')
321	          }
322	        }
323	      } catch(e) {}
324	    }
325	  }
326	
327	  // 第三步：缓存也没有 → 直接读文件（兜底）
328	  if (!mapData) {
329	    if (typeof global.addRuntimeLog === 'function') {
330	      global.addRuntimeLog('[detail] 缓存也没有，直接读 Map 文件', 'warn')
331	    }
332	    mapData = await this._readMapFileDirectly(id)
333	    if (mapData) {
334	      if (typeof global.addRuntimeLog === 'function') {
335	        global.addRuntimeLog('[detail] 直接读 Map 文件成功', 'success')
336	      }
337	    }
338	  }
339	
340	  if (!mapData) {
341	    this.errorMsg = '未找到数据 (ID=' + id + ')'
342	    this.loading = false
343	    return
344	  }
345	
346	  // 填充基础信息
347	  this.yearDisplay = mapData.yearDisplay || '未知'
348	  this.region = mapData.region || '未知'
349	  this.detailTitle = mapData.title || '未知事件'
350	  var fullKeywordList = [this.detailTitle]
351	
352	  // ==========================================================
353	  // 读 detail 文件
354	  // ==========================================================
355	  var detailData = await this._readDetailFileDirectly(id)
356	  if (detailData) {
357	    if (detailData.restKeywords && detailData.restKeywords.length > 0) {
358	      fullKeywordList = fullKeywordList.concat(detailData.restKeywords)
359	    }
360	    this.cause = detailData.cause || ''
361	    this.impact = detailData.impact || ''
362	  } else {
363	    this.cause = ''
364	    this.impact = ''
365	  }
366	
367	  this.keywordList = fullKeywordList
368	  this.loading = false
369	
370	  if (typeof global.addRuntimeLog === 'function') {
371	    global.addRuntimeLog('[detail] 加载完成', 'info')
372	  }
373	},
374	
375	    // ============================================================
376	    // 从 storage 缓存加载 Map 到内存
377	    // ============================================================
378	    _loadMapFromCache(id) {
379	      var self = this
380	      return new Promise(function(resolve) {
381	        try {
382	          var engine = global.searchEngine
383	          if (!engine) {
384	            resolve(false)
385	            return
386	          }
387	
388	          var mapChunkSize = global.mapChunkSize || 100
389	          var mapId = Math.floor(id / mapChunkSize)
390	
391	          // 检查是否已经在内存中
392	          if (engine.mapData && engine.mapData[mapId]) {
393	            resolve(true)
394	            return
395	          }
396	
397	          // 从 storage 读取缓存
398	          var storageModule = require('@system.storage')
399	          var cacheKey = engine._getMapCacheKey ? engine._getMapCacheKey(mapId) : ('search_engine_map_v1_' + mapId)
400	
401	          storageModule.get({
402	            key: cacheKey,
403	            success: function(data) {
404	              try {
405	                var mapData = JSON.parse(data)
406	                if (!engine.mapData) engine.mapData = {}
407	                engine.mapData[mapId] = mapData
408	                if (typeof global.addRuntimeLog === 'function') {
409	                  global.addRuntimeLog('[detail] 从缓存加载 Map ' + mapId + ' 成功', 'success')
410	                }
411	                resolve(true)
412	              } catch(e) {
413	                resolve(false)
414	              }
415	            },
416	            fail: function() {
417	              resolve(false)
418	            }
419	          })
420	        } catch(e) {
421	          resolve(false)
422	        }
423	      })
424	    },
425	
426	    // ============================================================
427	    // 直接读 Map 文件（兜底）
428	    // ============================================================
429	    _readMapFileDirectly(id) {
430	      var self = this
431	      return new Promise(function(resolve) {
432	        try {
433	          var file = require('@system.file')
434	          var mapChunkSize = global.mapChunkSize || 100
435	          var chunkIndex = Math.floor(id / mapChunkSize)
436	          var mapPath = '/common/map_' + chunkIndex + '.txt'
437	
438	          file.readText({
439	            uri: mapPath,
440	            success: function(data) {
441	              try {
442	                var lines = data.text.split('\n').filter(function(line) { return line.trim() })
443	                for (var i = 0; i < lines.length; i++) {
444	                  var parts = lines[i].split('|')
445	                  if (parts.length < 4) continue
446	                  var mapId = parseInt(parts[0], 10)
447	                  if (mapId === id) {
448	                    resolve({
449	                      id: mapId,
450	                      year: parseInt(parts[1], 10),
451	                      yearDisplay: self._formatYearDisplay(parseInt(parts[1], 10)),
452	                      regionId: parseInt(parts[2], 10),
453	                      region: self._getRegionName(parseInt(parts[2], 10)),
454	                      title: parts[3] || '未知事件'
455	                    })
456	                    return
457	                  }
458	                }
459	                resolve(null)
460	              } catch(e) {
461	                resolve(null)
462	              }
463	            },
464	            fail: function(err, code) {
465	              resolve(null)
466	            }
467	          })
468	        } catch(e) {
469	          resolve(null)
470	        }
471	      })
472	    },
473	
474	    // ============================================================
475	    // 直接读 detail 文件
476	    // ============================================================
477	    _readDetailFileDirectly(id) {
478	      return new Promise(function(resolve) {
479	        try {
480	          var file = require('@system.file')
481	          var chunkSize = global.detailChunkSize || 100
482	          var chunkIndex = Math.floor(id / chunkSize)
483	          var offset = id % chunkSize
484	          var uri = '/common/detail_' + chunkIndex + '.txt'
485	
486	          file.readText({
487	            uri: uri,
488	            success: function(data) {
489	              try {
490	                var lines = data.text.split('\n')
491	                if (offset >= lines.length) {
492	                  resolve(null)
493	                  return
494	                }
495	                var parts = lines[offset].split('|')
496	                if (parts.length < 4) {
497	                  resolve(null)
498	                  return
499	                }
500	                var restStr = parts[1] || ''
501	                var restKeywords = restStr.split(',').filter(function(k) {
502	                  return k && k.trim() !== ''
503	                })
504	                resolve({
505	                  restKeywords: restKeywords,
506	                  cause: parts[2] || '',
507	                  impact: parts[3] || ''
508	                })
509	              } catch(e) {
510	                resolve(null)
511	              }
512	            },
513	            fail: function(err, code) {
514	              resolve(null)
515	            }
516	          })
517	        } catch(e) {
518	          resolve(null)
519	        }
520	      })
521	    },
522	
523	    // ============================================================
524	    // 获取地区名称
525	    // ============================================================
526	    _getRegionName(regionId) {
527	      var regionList = global.searchEngine ? global.searchEngine.getRegionList() : []
528	      var regionMap = {
529	        'asia': '亚洲',
530	        'europe': '欧洲',
531	        'africa': '非洲',
532	        'north_america': '北美洲',
533	        'south_america': '南美洲',
534	        'other': '其他'
535	      }
536	      var tag = (regionList && regionList[regionId]) ? regionList[regionId] : '未知'
537	      return regionMap[tag] || tag
538	    },
539	
540	    // ============================================================
541	    // 收藏功能
542	    // ============================================================
543	    checkFavoriteStatus(id) {
544	      var self = this
545	      storage.get({
546	        key: 'favorite_list',
547	        success: function(data) {
548	          try {
549	            var favorites = JSON.parse(data) || []
550	            var found = false
551	            for (var i = 0; i < favorites.length; i++) {
552	              var item = favorites[i]
553	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
554	              if (itemId === id) {
555	                found = true
556	                break
557	              }
558	            }
559	            self.isFavorited = found
560	          } catch(e) {
561	            self.isFavorited = false
562	          }
563	        },
564	        fail: function() {
565	          self.isFavorited = false
566	        }
567	      })
568	    },
569	
570	    toggleFavorite() {
571	      var self = this
572	
573	      if (this.eventId === undefined || this.eventId === null) {
574	        prompt.showToast({ message: '错误：事件ID无效', duration: 1000 })
575	        return
576	      }
