578	      var currentId = this.eventId
579	      var wasFavorited = this.isFavorited
580	
581	      var favoriteItem = {
582	        id: currentId,
583	        yearDisplay: this.yearDisplay || '未知',
584	        title: this.detailTitle || (this.keywordList && this.keywordList.length > 0 ? this.keywordList[0] : '未知事件'),
585	        region: this.displayRegion || '未知'
586	      }
587	
588	      storage.get({
589	        key: 'favorite_list',
590	        success: function(data) {
591	          var favorites = []
592	          try {
593	            favorites = JSON.parse(data) || []
594	          } catch(e) {
595	            favorites = []
