88	    refreshFavorites() {
89	      var self = this
90	      storage.get({
91	        key: 'favorite_list',
92	        success: function(data) {
93	          var list = []
94	          try {
95	            list = JSON.parse(data) || []
96	          } catch(e) {
97	            list = []
98	          }
99	          var normalized = list.map(function(item) {
100	            if (typeof item === 'number') {
101	              return { id: item, title: '事件 #' + item, yearDisplay: '', region: '' }
102	            }
103	            return {
104	              id: item.id || 0,
105	              title: item.title || '未知事件',
106	              yearDisplay: item.yearDisplay || '',
107	              region: item.region || ''
108	            }
109	          })
110	          self.favorites = normalized
111	          self.loading = false
112	        },
