139	        }
140	      }
141	      if (idx === -1) return
142	      var newFavorites = []
143	      for (var j = 0; j < this.favorites.length; j++) {
144	        if (j !== idx) {
145	          newFavorites.push(this.favorites[j])
146	        }
147	      }
