9	// 资料集图标生成：圆底 + 集名首字（规范 v1：每个资料包自带 icon.png）
10	function buildDatasetIcon(charText, bgColor, fgColor) {
11	  const ch = (charText || '资').charAt(0);
12	  const fontSize = 150;
13	  const cx = 128;
14	  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
15	  <circle cx="${cx}" cy="128" r="120" fill="${bgColor}"/>
16	  <text x="${cx}" y="128" font-family="sans-serif" font-size="${fontSize}" font-weight="bold" fill="${fgColor}" text-anchor="middle" dominant-baseline="central">${ch}</text>
17	</svg>`;
18	  return new Resvg(svg, { fitTo: { mode: 'width', value: 256 } }).render().asPng();
19	}
