21	const SRC = path.join(__dirname, '..', '..', '资料', 'poems_10000条_cleaned (1).txt');
22	const OUT = path.join(__dirname, '..', 'src', 'common', 'datasets', 'poems');
23	const DATASET_ID = 1;
24	const BUCKET_SIZE = 2048;
25	const MAP_CHUNK = 200;
26	const DETAIL_CHUNK = 100;
27	
28	// 与引擎完全一致的哈希（DJBXOR）
29	function hashCode(str) {
30	  let hash = 5381;
31	  for (let i = 0; i < str.length; i++) {
32	    hash = (hash * 33) ^ str.charCodeAt(i);
33	  }
34	  return hash >>> 0;
35	}
36	
37	// 与引擎 _parseQuery 对齐的分词：中文逐字、连续英文数字整词小写
38	function tokenize(text) {
39	  const tokens = [];
40	  const enRuns = text.match(/[a-zA-Z0-9]+/g) || [];
41	  for (const w of enRuns) tokens.push(w.toLowerCase());
42	  for (const ch of text) {
43	    if (/[\u4e00-\u9fa5]/.test(ch)) tokens.push(ch);
44	  }
45	  return [...new Set(tokens)];
46	}
47	
48	function main() {
49	  const raw = fs.readFileSync(SRC, 'utf-8');
50	  const lines = raw.split('\n').filter(l => l.trim());
51	  const records = [];
52	  const dynastySet = new Set();
53	
54	  for (const line of lines) {
55	    const parts = line.split('|');
56	    if (parts.length < 6) continue;
57	    const [, title, author, dynasty, source, content] = parts.map(p => p.trim().replace(/\|/g, '｜'));
58	    if (!title) continue;
59	    dynastySet.add(dynasty || '未知');
60	    records.push({ title, author, dynasty: dynasty || '未知', source, content });
61	  }
62	
63	  const dynasties = [...dynastySet].sort();
64	  const regionIndex = {};
65	  dynasties.forEach((d, i) => { regionIndex[d] = i; });
66	
67	  // 重编号 localId 0..N-1
68	  records.forEach((r, i) => { r.localId = i; });
69	
70	  // ---- map 分片（v4 引擎格式: localId|year(0)|regionId(朝代idx)|title(标题·作者)）----
71	  const mapFiles = [];
72	  for (let c = 0; c * MAP_CHUNK < records.length; c++) {
73	    const seg = records.slice(c * MAP_CHUNK, (c + 1) * MAP_CHUNK);
74	    const body = seg.map(r => `${r.localId}|0|${regionIndex[r.dynasty]}|${r.title}·${r.author}`).join('\n');
75	    mapFiles.push(body);
76	  }
77	
78	  // ---- detail 分片（v4 格式: localId|keywords|cause(出处)|impact(内容)）----
79	  const detailFiles = [];
80	  for (let c = 0; c * DETAIL_CHUNK < records.length; c++) {
81	    const seg = records.slice(c * DETAIL_CHUNK, (c + 1) * DETAIL_CHUNK);
82	    const body = seg.map(r => {
83	      const kw = [r.title, r.author, r.dynasty, r.source].filter(Boolean).join(',');
84	      const content = (r.content || '').replace(/\r?\n/g, '\\n');
85	      return `${r.localId}|${kw}|${r.source || ''}|${content}`;
86	    }).join('\n');
87	    detailFiles.push(body);
88	  }
89	
90	  // ---- 文本 block（bucketIdx|id1,id2,...）——关键词逐 token 入桶 ----
91	  const buckets = {};
92	  for (const r of records) {
93	    const kwText = [r.title, r.author, r.dynasty, r.source].filter(Boolean).join(',');
94	    for (const token of tokenize(kwText)) {
95	      const b = hashCode(token) % BUCKET_SIZE;
96	      if (!buckets[b]) buckets[b] = [];
97	      buckets[b].push(r.localId);
98	    }
99	  }
100	  const blockBody = Object.keys(buckets)
101	    .map(Number).sort((a, b) => a - b)
102	    .map(b => `${b}|${buckets[b].join(',')}`)
103	    .join('\n');
104	
105	  // ---- 写文件 ----
106	  fs.mkdirSync(OUT, { recursive: true });
107	  mapFiles.forEach((body, i) => fs.writeFileSync(path.join(OUT, `map_${i}.txt`), body, 'utf-8'));
108	  detailFiles.forEach((body, i) => fs.writeFileSync(path.join(OUT, `detail_${i}.txt`), body, 'utf-8'));
109	  fs.writeFileSync(path.join(OUT, 'block_0.txt'), blockBody, 'utf-8');
110	
111	  // ---- icon.png（资料集图标：圆底 + 集名首字）----
112	  fs.writeFileSync(path.join(OUT, 'icon.png'), buildDatasetIcon('诗', '#4D9FEE', '#FFFFFF'));
113	
114	  // ---- meta.txt（v4 引擎物化视图）----
115	  const meta = {
116	    totalCount: records.length,
117	    regionList: dynasties,
118	    categoryList: [],
119	    bucketSize: BUCKET_SIZE,
120	    chunks: [{ id: 0, bucketStart: 0, bucketEnd: BUCKET_SIZE - 1, recordCount: records.length }],
121	    maps: mapFiles.map((_, i) => ({
122	      startId: i * MAP_CHUNK,
123	      endId: Math.min((i + 1) * MAP_CHUNK, records.length) - 1
124	    })),
125	    mapChunkSize: MAP_CHUNK,
126	    detailChunkSize: DETAIL_CHUNK,
127	    version: 'poems-ds-1'
128	  };
129	  fs.writeFileSync(path.join(OUT, 'meta.txt'), JSON.stringify(meta), 'utf-8');
130	
131	  // ---- meta.json（规范 v1 自描述）----
132	  const metaJson = {
133	    datasetId: DATASET_ID,
134	    name: '诗词集',
135	    version: 1,
136	    category: '文化',
137	    author: 'sudo',
138	    totalCount: records.length,
139	    fields: {
140	      map: ['title', 'year', 'dynasty'],
141	      keyword: 'keywords',
142	      detail: ['source', 'content'],
143	      filter: ['dynasty']
144	    },
145	    mapChunkSize: MAP_CHUNK,
146	    detailChunkSize: DETAIL_CHUNK,
147	    blockCount: 1,
148	    bucketSize: BUCKET_SIZE,
149	    yearIndex: false,
150	    icon: 'icon.png'
151	  };
152	  fs.writeFileSync(path.join(OUT, 'meta.json'), JSON.stringify(metaJson, null, 2), 'utf-8');
153	
154	  console.log(`诗词资料集生成完成: ${records.length} 条, ${mapFiles.length} 个 map 片, ${detailFiles.length} 个 detail 片, ${dynasties.length} 个朝代`);
155	  console.log('输出目录:', OUT);
156	}
157	
158	main();
